import argparse
import csv
import sys


def count_nonnull(path):
    counts = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return counts
        for name in header:
            counts[name] = 0
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1
    return counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每列非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    try:
        counts = count_nonnull(args.csv_file)
    except FileNotFoundError:
        sys.exit(f"错误: 文件不存在: {args.csv_file}")

    if not counts:
        print("CSV 文件为空。")
        return

    for name, count in counts.items():
        print(f"{name}: {count}")


if __name__ == "__main__":
    main()
